import { announceBareHost, hostCapability } from "./registry.js";
const BARE = "This document is not connected to any records.";
function resolveWikiTarget(target) {
  const w = hostCapability("wikilinks");
  if (!w) {
    announceBareHost("wikilinks", "every [[link]] reads unavailable");
    return Promise.resolve({ status: "unavailable", title: target, message: BARE });
  }
  return w.resolve(target);
}
function createWikiPage(title) {
  const w = hostCapability("wikilinks");
  return w ? w.create(title) : Promise.resolve({ ok: false, error: BARE });
}
function loadWikiBody(token, id) {
  const w = hostCapability("wikilinks");
  return w ? w.loadBody(token, id) : Promise.resolve({ error: BARE });
}
export {
  createWikiPage,
  loadWikiBody,
  resolveWikiTarget
};
